import {readFile,writeFile,mkdir} from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
const target=path.resolve('./LOCAL_USER/AppData/Local/Temp/fvi-batch4-candidate-20260928'),out=path.resolve('output/access-mfa-parent-intake-20261005'),sha=x=>createHash('sha256').update(x).digest('hex');
const access=JSON.parse(await readFile('output/access-directory-dependency-recovery-20261005/RECOVERY-MANIFEST.json','utf8')),mfa=JSON.parse(await readFile('output/recovery-mfa-message-dependency-recovery-20261005/READY-MANIFEST.json','utf8'));
const items=[...access.files.map(x=>({file:x.path,image:x.recovered,sha256:x.sha256,tier:x.qualification})),...mfa.files.map(x=>({file:x.file,image:x.sourcePath,sha256:x.sha256,tier:x.qualification}))];
const plans=[];for(const x of items){const dest=path.resolve(target,x.file),src=path.resolve(x.image);if(!dest.startsWith(target+path.sep)||!src.startsWith(process.cwd()+path.sep)||!x.file.startsWith('src/'))throw new Error('Named source boundary');const bytes=await readFile(src);if(sha(bytes)!==x.sha256)throw new Error('Source image drift');let old=null;try{old=await readFile(dest);}catch(e){if(e.code!=='ENOENT')throw e;}plans.push({...x,dest,bytes,old});}
await mkdir(out,{recursive:true});const results=[];for(const x of plans){if(x.old&&sha(x.old)===x.sha256){results.push({file:x.file,sha256:x.sha256,tier:x.tier,alreadyExact:true});continue;}if(x.old){const b=path.resolve(out,'before',x.file);if(!b.startsWith(out+path.sep))throw new Error('Backup boundary');await mkdir(path.dirname(b),{recursive:true});await writeFile(b,x.old,{flag:'wx'});}await mkdir(path.dirname(x.dest),{recursive:true});await writeFile(x.dest,x.bytes);results.push({file:x.file,sha256:x.sha256,tier:x.tier,priorSha256:x.old?sha(x.old):null,parentCurrentReleaseQualificationRequired:true});}
await writeFile(out+'/INTAKE.json',JSON.stringify({at:new Date().toISOString(),results,wholeSourceQualified:false,canonicalDirtyWorkChanged:false,appUploaded:false},null,2),{flag:'wx'});console.log(JSON.stringify({intake:results.length,alreadyExact:results.filter(x=>x.alreadyExact).length,wholeSourceQualified:false,receipt:out+'/INTAKE.json'}));
